CREATE TABLE profiles(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE topics(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE skills(id TEXT PRIMARY KEY, topic_id TEXT REFERENCES topics(id), name TEXT NOT NULL);
CREATE TABLE prerequisites(skill_id TEXT REFERENCES skills(id), prerequisite_id TEXT REFERENCES skills(id), PRIMARY KEY(skill_id, prerequisite_id), CHECK(skill_id <> prerequisite_id));
CREATE TABLE tasks(id TEXT PRIMARY KEY, title TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, generator TEXT NOT NULL, seed INTEGER NOT NULL, parameters TEXT NOT NULL, difficulty REAL NOT NULL);
CREATE TABLE parts(task_id TEXT REFERENCES tasks(id), id TEXT NOT NULL, kind INTEGER NOT NULL, prompt TEXT NOT NULL, expression TEXT NOT NULL, max_score INTEGER NOT NULL CHECK(max_score > 0), PRIMARY KEY(task_id,id));
CREATE TABLE part_skills(task_id TEXT, part_id TEXT, skill_id TEXT REFERENCES skills(id), PRIMARY KEY(task_id,part_id,skill_id), FOREIGN KEY(task_id,part_id) REFERENCES parts(task_id,id));
CREATE TRIGGER immutable_task BEFORE UPDATE ON tasks WHEN OLD.published = 1 AND (NEW.title <> OLD.title OR NEW.published <> 1 OR NEW.generator <> OLD.generator OR NEW.seed <> OLD.seed OR NEW.parameters <> OLD.parameters OR NEW.difficulty <> OLD.difficulty) BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_task_delete BEFORE DELETE ON tasks WHEN OLD.published = 1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_parts_insert BEFORE INSERT ON parts WHEN (SELECT published FROM tasks WHERE id=NEW.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_parts_update BEFORE UPDATE ON parts WHEN (SELECT published FROM tasks WHERE id=OLD.task_id)=1 OR (SELECT published FROM tasks WHERE id=NEW.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_parts_delete BEFORE DELETE ON parts WHEN (SELECT published FROM tasks WHERE id=OLD.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_skills_insert BEFORE INSERT ON part_skills WHEN (SELECT published FROM tasks WHERE id=NEW.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_skills_delete BEFORE DELETE ON part_skills WHEN (SELECT published FROM tasks WHERE id=OLD.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TRIGGER immutable_skills_update BEFORE UPDATE ON part_skills WHEN (SELECT published FROM tasks WHERE id=OLD.task_id)=1 OR (SELECT published FROM tasks WHERE id=NEW.task_id)=1 BEGIN SELECT RAISE(ABORT, 'Published version is immutable'); END;
CREATE TABLE sessions(id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES profiles(id), mode INTEGER NOT NULL, feedback INTEGER NOT NULL, guided INTEGER NOT NULL, task_limit INTEGER NOT NULL CHECK(task_limit > 0));
CREATE TABLE session_tasks(session_id TEXT REFERENCES sessions(id), position INTEGER NOT NULL, task_id TEXT REFERENCES tasks(id), PRIMARY KEY(session_id,position));
CREATE TABLE attempts(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), position INTEGER NOT NULL, task_id TEXT NOT NULL REFERENCES tasks(id), finished INTEGER NOT NULL DEFAULT 0, score INTEGER NOT NULL DEFAULT 0, provisional INTEGER NOT NULL DEFAULT 1, UNIQUE(session_id,position));
CREATE TABLE responses(sequence INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT UNIQUE NOT NULL, attempt_id TEXT NOT NULL REFERENCES attempts(id), part_id TEXT NOT NULL, text TEXT NOT NULL, graph TEXT NOT NULL, status INTEGER NOT NULL, message TEXT NOT NULL, is_final INTEGER NOT NULL, operation TEXT NOT NULL, operand TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE help_events(request_id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), part_id TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE observations(attempt_id TEXT REFERENCES attempts(id), skill_id TEXT REFERENCES skills(id), correct INTEGER NOT NULL, eligible INTEGER NOT NULL, mastery_before REAL NOT NULL, rating_before REAL NOT NULL, known_before INTEGER NOT NULL, count_before INTEGER NOT NULL, model_version TEXT NOT NULL, PRIMARY KEY(attempt_id,skill_id));
CREATE TABLE student_skills(student_id TEXT REFERENCES profiles(id), skill_id TEXT REFERENCES skills(id), mastery REAL NOT NULL, rating REAL NOT NULL, observations INTEGER NOT NULL, PRIMARY KEY(student_id,skill_id));
CREATE TABLE model_parameters(version TEXT PRIMARY KEY, initial REAL NOT NULL, learn REAL NOT NULL, slip REAL NOT NULL, guess REAL NOT NULL, k REAL NOT NULL);
